{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "requests",
      "as": "filtered",
      "where": "status >= 500"
    },
    {
      "op": "select",
      "input": "filtered",
      "as": "result",
      "columns": ["status"]
    }
  ]
}

{
  "response_schema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "oneOf": [
      {
        "type": "object",
        "properties": {
          "status": {"const": "plan"},
          "steps": {
            "type": "array",
            "items": [
              {
                "type": "object",
                "properties": {
                  "op": {"const": "derive"},
                  "input": {"const": "employees"},
                  "as": {"const": "bonus"},
                  "column": {"const": "bonus"},
                  "expr": {"const": "salary * bonus_pct / 100"}
                },
                "required": ["op","column","expr"]
              }
            ]
          }
        },
        "required": ["status","steps"]
      }
    ]
  },
  "steps": [
    {
      "op": "derive",
      "input": "employees",
      "as": "bonus",
      "column": "bonus",
      "expr": "salary * bonus_pct / 100"
    }
  ]
}

{
  "response_schema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "oneOf": [
      {
        "type": "object",
        "properties": {
          "status": {
            "const": "plan"
          },
          "steps": {
            "type": "array",
            "items": [
              {
                "type": "object",
                "properties": {
                  "op": {
                    "const": "derive"
                  },
                  "input": {
                    "const": "trips"
                  },
                  "as": {
                    "const": "speed_kmh"
                  },
                  "column": {
                    "const": "speed_kmh"
                  },
                  "expr": {
                    "const": "round(distance_km / (duration_min / 60), 1)"
                  }
                },
                "required": [
                  "op",
                  "input",
                  "as",
                  "column",
                  "expr"
                ],
                "additionalProperties": false
              }
            ],
            "minItems": 1,
            "maxItems": 1
          }
        ],
        "required": [
          "status",
          "steps"
        ],
        "additionalProperties": false
      },
      {
        "type": "object",
        "properties": {
          "status": {
            "const": "unsupported"
          },
          "reason": {
            "type": "string"
          }
        },
        "required": [
          "status",
          "reason"
        ],
        "additionalProperties": false
      }
    ]
  },
  "steps": [
    {
      "op": "derive",
      "input": "trips",
      "as": "speed_kmh",
      "column": "speed_kmh",
      "expr": "round(distance_km / (duration_min / 60), 1)"
    }
  ]
}
